) -> CompileResult<'src, Alias<'src, Namepath<'src>>> {
  self.presume_keyword(Keyword::Alias)?;
  let name = self.parse_name()?;
  self.presume_any(&[Equals, ColonEquals])?;
  let target = self.parse_namepath()?;
