  async dispose(): Promise<void> {
    await this.#pending;
    this.#serializeAddon.dispose();
    this.#terminal.dispose();
  }

  #capture(atMs: number): void {
    const buffer = this.#terminal.buffer.active;
    const lines: string[] = [];
    for (let row = 0; row < this.#terminal.rows; row += 1) {
