            self.height = self.height.enclose(size_hint.height);
        }

        self
    }

    /// Creates a new [`Scrollable`] with the given [`Direction`].
    pub fn direction(mut self, direction: impl Into<Direction>) -> Self {
        self.direction = direction.into();
        self.validate()
    }

