  ]).map((path) => {
    let name = basename(path);
    if (name === 'index.ts' || name === 'index.js') {
      name = basename(resolve(path, '..'));
    }

    name = name.replace(extname(name), '');

    return { name, path };
  });

  const src = project.createSourceFile('vm:pluginIndexes', (writer) => {
