                    "status": "error",
                }
            },
        )

    result = {
        "image": {
            "prompt": prompt,
            "image_urls": unique_urls,
            "result_url": result_url,
            "status": "ok",
            "aspect_ratio": aspect_ratio,
        }
    }
    summary = {
